/// Where a TOML table BEGINS, as a byte offset — the start of the comment run written above its
/// header, not the header itself.
///
/// A `#` comment above a table describes THAT table, so inserting a new table at the header's own
/// offset lands it between the two and re-points the prose at the wrong thing. `bsc-sqlite-util` is
/// the measured case: `# Lib only — no binaries.` sits above `[lib]`, and `opt_in` put
/// `[build-dependencies]` underneath it, so the manifest read as if the build-dependencies table were
/// the lib-only one. Nothing about the build breaks, which is exactly why it would have stayed.
///
/// `None` when the table is not there. The header must be the WHOLE line — a `[lib]` inside a string
/// or a longer header (`[lib.something]`) is not this table.
pub(crate) fn table_start(cargo_toml: &str, header: &str) -> Option<usize> {
    let lines: Vec<&str> = cargo_toml.split('\n').collect();
    let at = lines.iter().position(|l| l.trim() == header)?;
    // Back up over the contiguous comment run directly above the header. A BLANK line ends the run:
    // a comment separated from the table by one is prose about the file, not about the table.
    let mut start = at;
    while start > 0 && lines[start - 1].trim_start().starts_with('#') {
        start -= 1;
    }
    Some(lines[..start].iter().map(|l| l.len() + 1).sum())
}
